  const idx=entryId?stack.findIndex(x=>x.id===entryId):0;
  if(idx===-1)return;
  const entry=stack[idx];
  setUndoStack(prev=>prev.filter(x=>x.id!==entry.id));
  undoingRef.current=true;
  try{
   await entry.undo();
   toast.success(`Undid: ${entry.label}`);
  }catch(e){
   toast.error((e as Error).message||'Could not undo action');
  }finally{
   undoingRef.current=false;
  }
