 const recordUndo=(label:string,undo:()=>void|Promise<void>,toastMsg?:string,toastKind:'success'|'info'='success')=>{
  const id=`undo-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;
  const entry:UndoEntry={id,label,undo};
  setUndoStack(prev=>[entry,...prev].slice(0,25));
  const msg=toastMsg||label;
  const opts={duration:6000,action:{label:'Undo',onClick:()=>{performUndoRef.current(id);}}};
  if(toastKind==='info')toast.info(msg,opts);
  else toast.success(msg,opts);
 };
 useEffect(()=>{
  const onKey=(e:KeyboardEvent)=>{
   if((e.metaKey||e.ctrlKey)&&!e.shiftKey&&e.key.toLowerCase()==='z'){
    const el=e.target as HTMLElement|null;
    if(el&&(el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement||el instanceof HTMLSelectElement||el.isContentEditable))return;
    if(!undoStackRef.current.length)return;
    e.preventDefault();
    performUndoRef.current();
   }
  };
  window.addEventListener('keydown',onKey);
  return()=>window.removeEventListener('keydown',onKey);
 },[]);

