   if(action==='supplier'){const n=String(values.name||'').trim();if(!n)return;const id=`preview-sup-${Date.now()}`;setData(prev=>normalize({...prev,suppliers:[...prev.suppliers,{id,name:n,service:'',contact:''}]}));toast.info(`Added ${label} "${n}" (training mode)`);return id;}
