   const r=await fetch('/api/workspace',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,values,revision})});
   const j=await r.json() as {state?:State;revision?:number;session?:typeof session;error?:string;createdId?:string;createdValue?:string};
   if(!r.ok){const msg=j.error||`Could not add ${label}.`;setError(msg);toast.error(msg);return;}
