 function myDayTaskTable(list:Task[],emptyMsg:string){return <div className="table-wrap"><table><thead><tr><th>Priority &amp; Task</th><th>Status / Complete</th><th>Owner</th><th>Due / Reschedule</th><th>Open</th></tr></thead><tbody>{list.map(t=>{const isPinned=pinnedIds.includes(t.id);return <tr key={t.id} className={isPinned?'priority-row':''}><td><div className="row"><button type="button" className={'pin-toggle'+(isPinned?' active':'')} disabled={!previewInteractive||busy} aria-label={isPinned?`Unpin ${t.name}`:`Pin ${t.name} as daily priority`} title={isPinned?'Unpin priority':'Pin daily priority'} onClick={()=>mutate('priorityPin',{taskId:t.id,pinned:!isPinned})}><Pin size={14}/></button><div className="grow"><strong>{t.name}</strong><small>{taskContextLabel(t)}{t.hat?` · ${t.hat}`:''}</small>{t.sourceNoteId&&(s.notes||[]).some(n=>n.id===t.sourceNoteId)&&<small>Created from workspace note</small>}</div></div></td><td><div className="quick-status-cell"><select disabled={!previewInteractive||busy} aria-label={`My Day status: ${t.name}`} value={t.status} onChange={e=>mutate('taskStatus',{id:t.id,status:e.target.value})}>{s.taskStatuses.map(st=><option key={st.name}>{st.name}</option>)}</select>{previewInteractive&&<button type="button" className="mini-btn" disabled={busy} onClick={()=>mutate('taskStatus',{id:t.id,status:doneStatusName},'Task completed')}><Check size={13}/>Done</button>}</div></td><td>{taskOwner(t)}</td><td><div className="quick-due-cell">{dueInput(t)}{previewInteractive&&<div className="shift-pills"><button type="button" className="mini-btn" disabled={busy||t.due===today} onClick={()=>mutate('taskEdit',{id:t.id,owner:t.owner,supplierId:t.supplierId,due:today,hat:t.hat},'Moved due date to today')}>Today</button><button type="button" className="mini-btn" disabled={busy} onClick={()=>mutate('taskEdit',{id:t.id,owner:t.owner,supplierId:t.supplierId,due:addDays(t.due||today,1),hat:t.hat},'Rescheduled +1 day')}>+1d</button><button type="button" className="mini-btn" disabled={busy} onClick={()=>mutate('taskEdit',{id:t.id,owner:t.owner,supplierId:t.supplierId,due:addDays(t.due||today,3),hat:t.hat},'Rescheduled +3 days')}>+3d</button></div>}</div></td><td><button className="edit-pill" onClick={()=>openTaskContext(t)}>{t.projectId?'Project':'Record'}</button></td></tr>})}</tbody></table>{!list.length&&<div className="empty">{emptyMsg}</div>}</div>}
 function projectList(list:Project[]){return <div className="table-wrap"><table><thead><tr><th>Project / brand</th><th>Status</th><th>Owner</th><th>Timeline</th><th>Progress</th><th>Waiting</th></tr></thead><tbody>{list.map(p=>{const pWait=openWaiting.filter(w=>w.projectId===p.id);return <tr key={p.id} onClick={()=>{setSelected(p.id);setPage('Projects')}} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'){setSelected(p.id);setPage('Projects')}}}><td><strong>{p.name}</strong><small>{cname(p.companyId)} <span> / </span> {bname(p.brandId)}</small></td><td>{badge(p.status)}</td><td><span className="avatar tiny">{p.owner.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>{p.owner}</td><td>{date(p.start)} – {date(p.due)}</td><td><div className="progress"><i style={{width:`${total(p)?done(p)/total(p)*100:0}%`}}/></div><small>{done(p)} / {total(p)} tasks</small></td><td><HoverPreview disabled={pWait.length===0} content={<div className="hp-body"><div className="hp-head"><strong>Waiting on ({pWait.length})</strong><span className="badge red">{p.name}</span></div>{pWait.slice(0,4).map(w=><div key={w.id} className="hp-note"><strong>{w.name}</strong> · {w.person} ({w.party}) · Due {date(w.due)}</div>)}</div>}><span className="wait-count">{pWait.length}</span></HoverPreview></td></tr>})}</tbody></table>{!list.length&&<div className="empty">No projects yet. Create one to start coordinating delivery.</div>}</div>}
 function waitingCards(items= openWaiting){return <div className="waiting-list">{items.filter(matches).map(w=>{const isOverdue=!w.resolved&&w.due<today;const ageLabel=formatWaitingAge(w.requested,today);return <article className="waiting-card" key={w.id}><div className={'wait-icon '+(isOverdue?'urgent':'')}><Clock3 size={20}/></div><div className="grow"><div className="row"><strong>{w.name}</strong><div className="actions">{!w.resolved&&<span className="origin-pill">{ageLabel}</span>}{badge(w.resolved?'Done':isOverdue?'Overdue':w.party)}</div></div><p><span className="muted">Project:</span> {name(w.projectId)}</p><small>{w.impact}</small><div className="waiting-facts"><span><strong>Owed by:</strong> {w.person} ({w.party})</span><span><strong>Chasing owner:</strong> {w.owner}</span><span><strong>Expected:</strong> {date(w.due)}</span><span><strong>Next chase:</strong> {date(w.followup)}</span><span><strong>Requested:</strong> {date(w.requested)}</span></div>{w.resolved&&<p className="resolution">Resolution: {w.resolution}{w.resolvedAt&&` · Resolved ${new Date(w.resolvedAt).toLocaleDateString('en-PH')}`}</p>}</div>{previewInteractive&&<div className="stack">{!w.resolved&&<button onClick={()=>open('resolve',w.id)}>Resolve</button>}<button className="text-button" onClick={()=>open('waitingEdit',w.id)}>Edit</button>{!w.resolved&&<button className="text-button" onClick={()=>open('followup',w.id)}>Schedule follow-up</button>}</div>}</article>})}{!items.length&&<div className="empty">Nothing waiting here. Keep the next action clear.</div>}</div>}
