 function startDealPointer(e:React.PointerEvent<HTMLElement>,o:State['opportunities'][number]){
  if(!canDragDeal||busy||e.button!==0||(e.target as HTMLElement).closest('select,input,textarea,summary,button,a,label,details[open]'))return;
  e.preventDefault();
  dragRef.current={id:o.id,x:e.clientX,y:e.clientY,active:false};
 }
 useEffect(()=>{
  const cancel=()=>{dragRef.current=null;setDragging('');setDropStage('');setDragPoint(null)};
  const onMove=(e:PointerEvent)=>{
   const d=dragRef.current;if(!d)return;
   if(e.buttons===0){cancel();return;}
   if(!d.active){
    if(Math.hypot(e.clientX-d.x,e.clientY-d.y)<6)return;
    d.active=true;setDragging(d.id);
   }
   const px=Math.max(8,Math.min(e.clientX+16,window.innerWidth-256));
   const py=Math.max(8,Math.min(e.clientY+16,window.innerHeight-110));
   setDragPoint({x:px,y:py});
   const lane=document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('[data-drop-stage]');
   setDropStage(lane?.dataset.dropStage||'');
  };
  const onUp=(e:PointerEvent)=>{
   const d=dragRef.current;if(!d)return;
   const stage=d.active?document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('[data-drop-stage]')?.dataset.dropStage:'';
   cancel();
   if(d.active&&stage)dealDropRef.current(d.id,stage);
  };
  const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')cancel()};
  window.addEventListener('pointermove',onMove);
  window.addEventListener('pointerup',onUp);
  window.addEventListener('pointercancel',cancel);
  window.addEventListener('blur',cancel);
  window.addEventListener('keydown',onKey);
  return()=>{window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',onUp);window.removeEventListener('pointercancel',cancel);window.removeEventListener('blur',cancel);window.removeEventListener('keydown',onKey)};
 },[]);
