 function saveShared<T extends {id:string}>(collection:'studioPins'|'meetings'|'retrospectives',before:T[],after:T[],setPreview:(items:T[])=>void,message:string){
  if(!canManageShared||busy)return;
  if(!signed){
   setPreview(after);
   recordUndo(message,()=>setPreview(before),message);
   return;
  }
  const prior=new Map(before.map(item=>[item.id,item]));
  const next=new Map(after.map(item=>[item.id,item]));
  const upserts=after.filter(item=>JSON.stringify(item)!==JSON.stringify(prior.get(item.id)));
  const removeIds=before.filter(item=>!next.has(item.id)).map(item=>item.id);
  if(!upserts.length&&!removeIds.length)return;
  const touched=new Set([...upserts.map(item=>item.id),...removeIds]);
  void mutate('sharedWork',{collection,upserts,removeIds},undefined,{skipUndo:true,onSaved:savedRevision=>{
   recordUndo(message,()=>mutateRef.current('sharedWork',{
    collection,upserts:before.filter(item=>touched.has(item.id)),
    removeIds:upserts.filter(item=>!prior.has(item.id)).map(item=>item.id)
   },undefined,{skipUndo:true,expectedRevision:savedRevision}),message);
  }});
 }
