 useEffect(()=>{
  const clearNavDrag=()=>{navDragRef.current=null;navDropRef.current=null;setDraggingNav('');setNavDropTarget(null)};
  const onMove=(e:PointerEvent)=>{
   const d=navDragRef.current;if(!d)return;
   if(e.buttons===0){clearNavDrag();return;}
   if(!d.active){
    if(Math.abs(e.clientY-d.y)<5)return;
    d.active=true;suppressNavClickRef.current=true;setDraggingNav(d.label);
   }
   const el=document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('[data-nav-item]');
   const targetLabel=el?.dataset.navItem||'';
   if(!targetLabel||targetLabel===d.label){navDropRef.current=null;setNavDropTarget(null);return;}
   const rect=el!.getBoundingClientRect();
   const position:'before'|'after'=e.clientY<rect.top+rect.height/2?'before':'after';
   const nextTarget={label:targetLabel,position};
   navDropRef.current=nextTarget;setNavDropTarget(nextTarget);
  };
  const onUp=()=>{
   const d=navDragRef.current;if(!d)return;
   const target=navDropRef.current;
   const wasActive=d.active;
   clearNavDrag();
   if(wasActive){
    if(target&&target.label!==d.label){
     const prevOrder=[...navOrderRef.current];
     const cur=[...prevOrder];
     const fromIdx=cur.indexOf(d.label);
     if(fromIdx!==-1){
      cur.splice(fromIdx,1);
      let toIdx=cur.indexOf(target.label);
      if(toIdx!==-1){
       if(target.position==='after')toIdx+=1;
       cur.splice(toIdx,0,d.label);
       saveNavOrderRef.current(cur);
       recordUndoRef.current('Reorder sidebar',()=>saveNavOrderRef.current(prevOrder),'Sidebar order updated','info');
      }
     }
    }
    window.setTimeout(()=>{suppressNavClickRef.current=false;},120);
   }
  };
  const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')clearNavDrag()};
  window.addEventListener('pointermove',onMove);
  window.addEventListener('pointerup',onUp);
  window.addEventListener('pointercancel',clearNavDrag);
  window.addEventListener('blur',clearNavDrag);
  window.addEventListener('keydown',onKey);
  return()=>{window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',onUp);window.removeEventListener('pointercancel',clearNavDrag);window.removeEventListener('blur',clearNavDrag);window.removeEventListener('keydown',onKey)};
 },[]);
