 async function unlockNote(n:Note,passcode:string):Promise<string|null>{
  if(!signed){
   const rec=previewLockedRef.current[n.id];
   if(!rec||rec.passcode!==passcode)return 'Incorrect passcode';
   setUnlockedNotes(prev=>({...prev,[n.id]:{text:rec.text,edits:rec.edits,passcode}}));
   toast.info('Preview: note unlocked');
   return null;
  }
  try{
   const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'noteUnlock',values:{id:n.id,passcode},revision})});
   const j=await r.json().catch(()=>({})) as {error?:string;unlocked?:boolean;text?:string;edits?:Note['edits']};
   if(!r.ok||!j.unlocked)return j.error||'Incorrect passcode';
   setUnlockedNotes(prev=>({...prev,[n.id]:{text:j.text||'',edits:j.edits||[],passcode}}));
   toast.success('Note unlocked for this session');
   return null;
  }catch{return 'Could not verify passcode';}
 }
